from pathlib import Path
import json

EDITS=json.loads("[[\"tests/WindowsVst3HostPcmSmoke.cpp\",\"        unsigned lateCallbacks=0;\\n        bool measure=false;\",\"        unsigned lateCallbacks=0;\\n        awe64::qa::SchedWindow worstCallback{};\\n        const auto callbackTid=GetCurrentThreadId();\\n        bool measure=false;\"],[\"tests/WindowsVst3HostPcmSmoke.cpp\",\"            const auto before=Clock::now();\\n            if(processor->process(data)!=S::kResultOk)return false;\\n            const auto after=Clock::now();\",\"            const auto qpcBefore=measure?preciseCpu.now():0;\\n            const auto before=Clock::now();\\n            if(processor->process(data)!=S::kResultOk)return false;\\n            const auto after=Clock::now();\\n            const auto qpcAfter=measure?preciseCpu.now():0;\"],[\"tests/WindowsVst3HostPcmSmoke.cpp\",\"                maxCallbackMs=std::max(maxCallbackMs,elapsed);\",\"                if(elapsed>maxCallbackMs)worstCallback={qpcBefore,qpcAfter};\\n                maxCallbackMs=std::max(maxCallbackMs,elapsed);\"],[\"tests/WindowsVst3HostPcmSmoke.cpp\",\"        const bool traceOk=preciseCpu.finish(cpuWindows,scheduled);\",\"        double worstScheduledRatio=-1.;\\n        const bool traceOk=preciseCpu.finish(cpuWindows,scheduled,&worstCallback,callbackTid,&worstScheduledRatio);\\n        std::cout<<\\\"AUDIT_WORST_CALLBACK wall_ms=\\\"<<maxCallbackMs<<\\\" budget_ms=\\\"<<blockMs\\n                 <<\\\" scheduled_ratio=\\\"<<worstScheduledRatio<<\\\" thread_id=\\\"<<callbackTid<<\\\"\\\\n\\\";\"],[\"tests/WindowsScheduledCpuTrace.hpp\",\"    bool finish(const std::array<SchedWindow,N>& windows,std::array<double,N>& ratios) {\",\"    bool finish(const std::array<SchedWindow,N>& windows,std::array<double,N>& ratios,\\n                const SchedWindow* extra=nullptr,std::uint32_t tid=0,double* extraRatio=nullptr) {\"],[\"tests/WindowsScheduledCpuTrace.hpp\",\"        for(std::size_t i=0;i<N;++i)ratios[i]=double(totals[i])/double(windows[i].end-windows[i].begin);\\n        return true;\",\"        for(std::size_t i=0;i<N;++i)ratios[i]=double(totals[i])/double(windows[i].end-windows[i].begin);\\n        if(extra&&extraRatio&&tid){\\n            std::array<SchedWindow,1> w{*extra};std::array<std::uint64_t,1> t{};\\n            if(scheduledTime(events_,GetCurrentProcessId(),w,t,tid))\\n                *extraRatio=double(t[0])/double(w[0].end-w[0].begin);\\n        }\\n        return true;\"],[\"tests/ScheduledCpuTime.hpp\",\"                   std::array<std::uint64_t,N>& totals) {\",\"                   std::array<std::uint64_t,N>& totals,std::uint32_t onlyTid=0) {\"],[\"tests/ScheduledCpuTime.hpp\",\"        if(e.kind==SchedKind::Start){if(e.b==pid)owned.insert(e.a);else owned.erase(e.a);continue;}\",\"        if(e.kind==SchedKind::Start){if(e.b==pid&&(!onlyTid||onlyTid==e.a))owned.insert(e.a);else owned.erase(e.a);continue;}\"]]")
for filename,old,new in EDITS:
    p=Path(filename)
    s=p.read_text(encoding='utf-8')
    if s.count(old)!=1:
        raise RuntimeError('Unexpected source anchor '+filename)
    p.write_text(s.replace(old,new),encoding='utf-8')
print('CALLBACK_DIAGNOSTIC_HOST_PATCHED; PRODUCT_UNCHANGED')
